
const icons={home:'<path d="m3 10 9-7 9 7v10h-6v-6H9v6H3z"/>',book:'<path d="M12 5v15M3 4c3-1 6 0 9 1 3-1 6-2 9-1v15c-3-1-6 0-9 1-3-1-6-2-9-1z"/>',check:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="15" cy="17" r="3" fill="white"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v5l2 3H4l2-3zM10 21h4"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 14 6M18 18A8 8 0 0 1 4 12"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 13h8M8 17h6"/>',link:'<path d="M14 3h7v7M21 3 10 14M11 5H3v16h16v-8"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>'};const ic=(n)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const API=['localhost','127.0.0.1'].includes(location.hostname)&&location.port==='8787'?location.origin:'https://coursecue.hrk-6888.workers.dev';
let courses=['人材マネジメントⅡ','コーポレートファイナンスⅡ','国際ビジネス戦略','サービス・マーケティング','意思決定論','管理会計Ⅱ','マーケティング戦略','ボランティア','経営科学Ⅱ','経済言論Ⅱ','言葉と文化'];
const statuses={ready:['未着手',''],answered:['本人の提出待ち','wait'],wait:['要確認','wait'],code:['出席コード待ち','wait'],draft:['下書き','draft'],done:['提出済み','done'],unknown:['提出結果不明','wait']};let state={tasks:[],materials:[],settings:{time:'16:30'}},view='home',filter='all',query='',selectedCourse=null,lastFocus=null,key=localStorage.getItem('coursecue-owner')||'',busy=false;
const ownerCourses=[...courses];let guestData;try{guestData=JSON.parse(localStorage.getItem('coursecue-personal')||'null')}catch{}if(!key){courses=guestData?.courses||[];state=guestData?.state||{tasks:[],materials:[],settings:{time:'16:30'}};}function savePersonal(){localStorage.setItem('coursecue-personal',JSON.stringify({courses,state}));}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=s=>s?new Date(s).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'未確認';const needs=t=>['wait','code','unknown','answered'].includes(t.status);const soon=t=>t.status!=='done'&&t.dueAt&&new Date(t.dueAt)-Date.now()<=3*86400000&&new Date(t.dueAt)>new Date();
async function api(path,method='GET',data){const r=await fetch(API+path,{method,headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});if(r.status===401)throw Error('Macから接続してください');if(!r.ok)throw Error('接続できません');return r.json()}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>e.style.display='none',5000)}
async function load(){if(document.activeElement?.matches('input,textarea,select'))return;if(!key){render();return}try{state=await api('/api/state');render()}catch(e){toast(e.message);render()}}
async function job(kind,task=null,payload={}){if(!key){const t=state.tasks.find(t=>t.id===task);if(kind==='supplement'&&t){t.answer=payload.answer;t.supplement=payload.text;}else if(kind==='submit'&&t){t.status='done';t.submittedAt=new Date().toISOString();}else {toast('manabo連携が必要です');return;}savePersonal();render();toast('保存しました');return;}try{await api('/api/jobs','POST',{kind,task,payload});toast('処理を予約しました');await load()}catch(e){toast(e.message)}}
function nav(){const n=state.tasks.filter(needs).length;document.querySelector('.nav').innerHTML=[['home','home','ホーム'],['courses','book','授業'],['tasks','check','課題'],['needs','clock','要対応'],['settings','settings','設定']].map(([v,i,l])=>`<button data-view="${v}" class="${view===v?'active':''}">${ic(i)}${l}${v==='needs'&&n?`<span class="count">${n}</span>`:''}</button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selectedCourse=null;filter='all';render();scrollTo(0,0)})}
function row(t){const [label,cl]=statuses[t.status]||['未確認',''];return `<button class="task" style="width:100%;text-align:left" data-task="${esc(t.id)}"><span class="courseicon">${esc(courses[t.course]?.[0]||'学')}</span><span><h3>${esc(t.title)}</h3><span class="meta">${esc(courses[t.course])} · ${t.round?'第'+t.round+'回':'回数未確認'} · ${esc(t.type)}</span>${needs(t)?`<span class="rowaction" style="display:block">${esc(t.action)}</span>`:''}</span><span class="right"><span class="badge ${cl}">${label}</span><span class="deadline">${t.dueAt?when(t.dueAt):'締切未確認'}</span></span></button>`}
function matched(t){return(!query||(courses[t.course]+t.title).includes(query))&&(selectedCourse===null||selectedCourse===t.course)&&(filter==='all'||filter==='pending'&&t.status!=='done'||filter==='done'&&t.status==='done'||filter==='soon'&&soon(t))}
function list(rows,tabs=true){return `${tabs?`<div class="tabs">${[['all','すべて'],['pending','未提出'],['done','提出済み'],['soon','3日以内']].map(([v,l])=>`<button class="tab ${v===filter?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div>`:''}<div class="tasklist">${rows.filter(matched).sort((a,b)=>(new Date(a.dueAt||'2099')-new Date(b.dueAt||'2099'))).map(row).join('')||'<div class="empty">課題なし</div>'}</div>`}
function cards(){return `<div class="coursegrid">${courses.map((c,i)=>({c,i})).filter(({c})=>!query||c.includes(query)).map(({c,i})=>{const ts=state.tasks.filter(t=>t.course===i);return `<button class="coursecard" data-course="${i}"><h3>${esc(c)}</h3><div class="bottom"><span>課題 ${ts.length}</span><span>未提出 ${ts.filter(t=>t.status!=='done').length}</span></div></button>`}).join('')}</div>`}
function render(){nav();document.getElementById('breadcrumb').textContent={home:'ホーム',courses:'授業',tasks:'課題',needs:'要対応',settings:'設定'}[view];document.querySelector('.topright>.demo').textContent=key?(state.running?'処理中':state.lastSync?'同期 '+when(state.lastSync):'同期待ち'):'このブラウザに保存';document.querySelector('.syncmini').innerHTML=`自動確認 ${esc(state.settings?.time||'16:30')}<br><span style="color:var(--muted)">${state.deviceSeen&&Date.now()-new Date(state.deviceSeen)<60000?'Mac 接続中':'Mac 未接続'}</span>`;if(!key)document.querySelector('.syncmini').textContent='個人用 · このブラウザに保存';const refresh=key?`<button class="btn" id="sync">${ic('refresh')}同期</button>`:'<button class="btn primary" id="addtask">課題を追加</button>';let html=`<section class="hero"><h1>${{home:'ホーム',courses:selectedCourse===null?'授業':courses[selectedCourse],tasks:'課題',needs:'要対応',settings:'設定'}[view]}</h1>${view!=='settings'?refresh:''}</section>`;
if(view==='home'){html+=`<section class="stats">${[['pending','未提出',state.tasks.filter(t=>t.status!=='done').length],['needs','要対応',state.tasks.filter(needs).length],['soon','3日以内',state.tasks.filter(soon).length],['done','提出済み',state.tasks.filter(t=>t.status==='done').length]].map(([v,l,n])=>`<button class="stat ${v==='needs'?'warn':''}" data-stat="${v}"><div class="label">${l}</div><div class="num">${n}<span>件</span></div></button>`).join('')}</section><section class="tasksection"><div class="sectionhead"><h2>未提出の課題</h2><small>締切順</small></div>${list(state.tasks.filter(t=>t.status!=='done'),false)}</section>`;if(state.lastError)html+=`<div class="panel" style="color:var(--amber)">${esc(state.lastError)} <a href="http://127.0.0.1:8766/setup" target="_blank">Mac設定</a></div>`;html+=`<section class="courses"><div class="sectionhead"><h2>授業</h2></div>${cards()}</section>`}
else if(view==='courses'){html+=selectedCourse===null?cards():`<button class="tab" id="back">← 授業</button>${list(state.tasks)}<h3>資料</h3>${state.materials.filter(m=>m.course===courses[selectedCourse]).map(m=>`<a class="btn" href="${esc(m.url)}" target="_blank" rel="noopener">${esc(m.name)}</a>`).join('')}`}
else if(view==='tasks'||view==='needs')html+=list(view==='needs'?state.tasks.filter(needs):state.tasks,view!=='needs');
else if(!key){html+=`<div class="panel"><b>授業</b><div class="field"><label for="newcourse">授業名</label><input id="newcourse" placeholder="授業名"></div><button class="btn primary" id="addcourse">追加</button></div><div class="panel"><b>データ</b><p>このブラウザに保存。別の端末ではバックアップを読み込んでください。</p><button class="btn" id="exportpersonal">バックアップ</button><label class="btn" for="importpersonal">読み込む</label><input id="importpersonal" type="file" accept="application/json"></div><details class="panel"><summary>manabo連携</summary><p>現在の自動連携は、登録済みMacを使用します。</p><a class="btn" href="http://127.0.0.1:8766/setup" target="_blank" rel="noopener">Macを接続</a></details>`}else {html+=`<div style="max-width:760px"><div class="panel"><b>manabo連携</b><div class="info-row"><span>認証情報</span>${state.credentialsConfigured?'キーチェーン保存済み':'未設定'}</div><div class="field"><label for="manabo-id">manabo ID</label><input id="manabo-id" autocomplete="username"></div><div class="field"><label for="manabo-password">パスワード</label><input id="manabo-password" type="password" autocomplete="current-password"></div><button class="btn primary" id="savecredentials">保存</button> <button class="btn" id="verifylogin">接続確認</button><p style="font-size:11px;color:var(--muted)">暗号化してMacのキーチェーンに保存します。</p></div><div class="panel"><b>自動処理</b><div class="field"><label for="time">実行時刻（日本時間）</label><input type="time" id="time" value="${esc(state.settings?.time||'16:30')}"></div><label><input type="checkbox" id="autogen" ${state.settings?.autoGenerate!==false?'checked':''}> 自動課題生成</label><br><p>クイズ：自動回答後、本人がmanaboで提出</p><p style="font-size:11px;color:var(--muted)">出席コードあり：問題のみ回答・提出待ち</p><button class="btn primary" id="savesettings">保存</button></div><div class="panel"><b>授業日</b><p style="font-size:11px;color:var(--muted)">初回日から週ごとの日程を設定。休講・変更日は個別設定してください。</p>${courses.map((c,i)=>`<div class="field"><label>${c} · 第1回</label><input type="date" data-schedule="${i}" value="${esc(state.schedules?.[courseIds[i]]?.[1]||'')}"></div>`).join('')}<button class="btn" id="saveschedule">日程を保存</button></div><button class="btn" id="logout">この端末の接続を解除</button></div>`}
if(!key&&!courses.length&&view!=='settings')html=`<section class="hero"><h1>授業を追加</h1></section><div class="panel"><div class="field"><label for="newcourse">授業名</label><input id="newcourse" placeholder="授業名"></div><button class="btn primary" id="addcourse">追加</button></div>`;document.getElementById('app').innerHTML=html;const bind=(id,f)=>{const e=document.getElementById(id);if(e)e.onclick=f};bind('addcourse',()=>{const name=document.getElementById('newcourse').value.trim();if(!name)return;if(courses.includes(name)){toast('登録済みの授業です');return}courses.push(name);savePersonal();view='home';render();});bind('addtask',()=>{if(!courses.length){view='settings';render();return}document.getElementById('drawer').innerHTML=`<h2>課題を追加</h2><div class="field"><label for="tasktitle">課題名</label><input id="tasktitle"></div><div class="field"><label for="taskcourse">授業</label><select id="taskcourse">${courses.map((c,i)=>`<option value="${i}">${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="taskdue">締切</label><input id="taskdue" type="datetime-local"></div><button class="btn primary" id="createtask">追加</button> <button class="btn" id="cancelcreate">キャンセル</button>`;document.getElementById('overlay').classList.add('open');document.getElementById('cancelcreate').onclick=close;document.getElementById('createtask').onclick=()=>{const title=document.getElementById('tasktitle').value.trim(),due=document.getElementById('taskdue').value;if(!title){toast('課題名を入力してください');return}state.tasks.push({id:crypto.randomUUID(),title,course:+document.getElementById('taskcourse').value,dueAt:due?new Date(due).toISOString():null,status:'ready',type:'課題',answer:'',description:'',url:''});savePersonal();close();render();};});bind('exportpersonal',()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify({version:1,courses,state})],{type:'application/json'}));a.href=u;a.download='CourseCue-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});const importer=document.getElementById('importpersonal');if(importer)importer.onchange=async()=>{try{const d=JSON.parse(await importer.files[0].text());if(d.version!==1||!Array.isArray(d.courses)||!d.courses.every(c=>typeof c==='string')||!Array.isArray(d.state?.tasks)||!Array.isArray(d.state?.materials)||d.state.tasks.some(t=>typeof t.id!=='string'||typeof t.title!=='string'||!Number.isInteger(t.course)||t.course<0||t.course>=d.courses.length))throw Error();if(!confirm('このブラウザのデータをバックアップで置き換えますか？'))return;courses=d.courses;state=d.state;savePersonal();render();toast('読み込みました');}catch{toast('バックアップを確認してください');}};bind('sync',()=>job('sync'));bind('verifylogin',()=>job('verify'));bind('savecredentials',async()=>{const username=document.getElementById('manabo-id').value.trim(),password=document.getElementById('manabo-password').value;if(!username||!password){toast('ID・パスワードを入力してください');return}if(!state.credentialPublicKey){toast('Macの接続を確認してください');return}try{const {encryptCredentials}=await import('./credentials.js');const payload=await encryptCredentials(state.credentialPublicKey,username,password);await api('/api/jobs','POST',{kind:'credentials',payload});document.getElementById('manabo-password').value='';toast('保存を予約しました。Macで処理します。');}catch{toast('保存できませんでした');}});bind('back',()=>{selectedCourse=null;render()});bind('logout',()=>{key='';localStorage.removeItem('coursecue-owner');courses=guestData?.courses||[];state=guestData?.state||{tasks:[],materials:[],settings:{time:'16:30'}};render()});bind('savesettings',()=>job('settings',null,{time:document.getElementById('time').value,autoGenerate:document.getElementById('autogen').checked,autoSubmitQuiz:false}));bind('saveschedule',()=>{const schedules={...state.schedules};document.querySelectorAll('[data-schedule]').forEach(e=>{if(!e.value)return;const dates={};for(let n=1;n<=15;n++){const d=new Date(e.value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7*(n-1));dates[n]=d.toISOString().slice(0,10)}schedules[courseIds[+e.dataset.schedule]]=dates});job('settings',null,{schedules})});document.querySelectorAll('[data-stat]').forEach(e=>e.onclick=()=>{view=e.dataset.stat==='needs'?'needs':'tasks';filter=e.dataset.stat==='needs'?'all':e.dataset.stat;render()});document.querySelectorAll('[data-filter]').forEach(e=>e.onclick=()=>{filter=e.dataset.filter;render()});document.querySelectorAll('[data-course]').forEach(e=>e.onclick=()=>{view='courses';selectedCourse=+e.dataset.course;render()});document.querySelectorAll('[data-task]').forEach(e=>e.onclick=()=>detail(e.dataset.task))}
const courseIds=['103578','103901','103576','103573','103889','103904','103572','103736','103887','103914','104493'];
function detail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;lastFocus=document.activeElement;document.getElementById('drawer').innerHTML=`<div class="drawerhead"><span>${esc(courses[t.course])} · ${t.round?'第'+t.round+'回':'回数未確認'}</span><button class="iconbtn" id="close" aria-label="閉じる">${ic('close')}</button></div><h2 id="drawer-title">${esc(t.title)}</h2><span class="badge">${statuses[t.status]?.[0]||'未確認'}</span><div class="panel"><b>締切</b> ${when(t.dueAt)}<br><b>最終確認</b> ${when(t.checkedAt)}${t.action?'<p>'+esc(t.action)+'</p>':''}</div><h3>設問</h3><p style="white-space:pre-wrap;font-size:12px;line-height:1.8">${esc(t.description)}</p><h3>回答・下書き</h3><textarea id="answer" aria-label="回答・下書き">${esc(t.answer)}</textarea><h3>本人の経験・補足</h3><textarea id="supplement" aria-label="本人の経験・補足">${esc(t.supplement||'')}</textarea><div class="actions"><button class="btn" id="save">保存</button><button class="btn primary" id="generate">課題を生成</button></div><div class="actions"><button class="btn" id="download">ダウンロード</button>${!['done','code','unknown','answered'].includes(t.status)&&t.type!=='クイズ'?'<button class="btn" id="submit">'+(key?'提出':'提出済みにする')+'</button>':''}</div><div class="actions">${t.url?`<a class="btn" href="${esc(t.url)}" target="_blank" rel="noopener">manabo</a>`:''}${['code','answered'].includes(t.status)?'<a class="btn" href="http://127.0.0.1:8766/browser" target="_blank">待機中のブラウザ</a>':''}</div><h3>根拠</h3><div style="font-size:12px;white-space:pre-wrap">${esc(t.generation?.answers?.map(a=>a.evidence).join('\n\n')||'未生成')}</div>`;document.getElementById('overlay').classList.add('open');document.body.style.overflow='hidden';document.getElementById('close').onclick=close;document.getElementById('close').focus();document.getElementById('save').onclick=()=>job('supplement',id,{text:document.getElementById('supplement').value,answer:document.getElementById('answer').value});document.getElementById('generate').onclick=async()=>{await job('supplement',id,{text:document.getElementById('supplement').value,answer:document.getElementById('answer').value});await job('generate',id)};const sub=document.getElementById('submit');if(sub)sub.onclick=()=>{if(confirm(key?'この課題をmanaboに提出しますか？':'提出済みとして記録しますか？'))job('submit',id)};document.getElementById('download').onclick=()=>{const url=URL.createObjectURL(new Blob([document.getElementById('answer').value],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download=`${t.round?'第'+t.round+'回_':''}${t.title}_下書き.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function close(){document.getElementById('overlay').classList.remove('open');document.body.style.overflow='';lastFocus?.focus()}
document.getElementById('searchicon').innerHTML=ic('search');document.getElementById('bellicon').innerHTML=ic('bell');document.getElementById('search').oninput=e=>{query=e.target.value;render()};document.getElementById('notifications').onclick=()=>{view='needs';render()};document.getElementById('overlay').onclick=e=>{if(e.target.id==='overlay')close()};document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&document.getElementById('overlay').classList.contains('open')){const es=[...document.querySelectorAll('#drawer button,#drawer a,#drawer textarea')],first=es[0],last=es.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('connect')){courses=ownerCourses;state={tasks:[],materials:[],settings:{time:'16:30'}};key=fragment.get('connect');history.replaceState(null,'',location.pathname);localStorage.setItem('coursecue-owner',key)}render();load();setInterval(load,15000);
